  (()=>{
    const form=document.querySelector('#caseForm'),result=document.querySelector('#result'),error=document.querySelector('#formError');
    const labels={medicamento:'entrega de un medicamento',procedimiento:'autorización de un procedimiento',especialista:'asignación de cita o especialista',continuidad:'continuidad de un tratamiento',negacion:'negación de un servicio'};
    const entityLabels={eps:'EPS',ips:'IPS, clínica u hospital',pharmacy:'farmacia o proveedor',unknown:'entidad por confirmar'};
    const escape=v=>String(v||'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
    const draft=()=>{try{return JSON.parse(sessionStorage.getItem('salvacion-m-contacto')||'{}')}catch{return {}}};
    const allAnswered=()=>['problem','urgent','entity_choice','support','time'].every(name=>form.querySelector(`input[name="${name}"]:checked`));
    const goHome=()=>{location.hash='inicio';document.querySelector('#inicio').scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth'});};
    form.addEventListener('submit',event=>{
      event.preventDefault();event.stopImmediatePropagation();
      if(!allAnswered()){error.textContent='Completa cada pregunta antes de ver tu orientación.';return}
      const answers=Object.fromEntries(new FormData(form).entries());
      form.hidden=true;result.hidden=false;
      if(answers.urgent==='yes'){
        result.innerHTML='<p class="eyebrow">Atención prioritaria</p><h3>No esperes una orientación digital</h3><div class="urgent"><b>Si existe riesgo inmediato para la vida o la integridad, acude a un servicio de urgencias o utiliza los canales oficiales de emergencia.</b></div><p>Salvación M no presta atención médica ni realiza triage clínico.</p><button class="button ghost" type="button" id="restart">Volver a empezar</button>';
        result.querySelector('#restart').onclick=()=>{result.hidden=true;form.hidden=false;form.reset();goHome()};result.focus({preventScroll:true});result.scrollIntoView({behavior:'smooth',block:'start'});return;
      }
      const saved=draft();
      result.innerHTML=`<div class="save-confirmation" role="status"><span class="save-confirmation-mark" aria-hidden="true">✓</span><div><strong>Respuestas guardadas temporalmente</strong><p>Ya generamos tu orientación. Autoriza el tratamiento de datos para enviar la solicitud a Salvación M.</p></div></div><p class="eyebrow">Ruta preliminar</p><h3>Solicitud para ${labels[answers.problem]}</h3><p>La entidad identificada es: <b>${entityLabels[answers.entity_choice]}</b>. Al enviar, el equipo recibirá tu solicitud para revisar el alcance de la orientación.</p><form id="contactForm" class="lead-form"><label>Nombres<input name="first_name" autocomplete="given-name" required maxlength="80" value="${escape(saved.first_name)}"></label><label>Apellidos<input name="last_name" autocomplete="family-name" required maxlength="80" value="${escape(saved.last_name)}"></label><label>Teléfono o WhatsApp<input name="phone" inputmode="tel" autocomplete="tel" required pattern="[0-9 +()-]{7,20}" maxlength="20" value="${escape(saved.phone)}"></label><label>Dirección de residencia<input name="address" autocomplete="street-address" required maxlength="180" value="${escape(saved.address)}"></label><label>Correo electrónico<input name="email" type="email" autocomplete="email" required maxlength="160" value="${escape(saved.email)}"></label><label>Fecha y hora preferida, si deseas proponer una cita (hora de Colombia)<input name="preferred_at" type="datetime-local"></label><label>Resumen breve, sin historia clínica<textarea name="summary" maxlength="500"></textarea></label><label class="consent"><input name="consent" type="checkbox" required><span>Autorizo a Salvación M el tratamiento de mis datos de identificación, contacto, residencia y respuestas para gestionar esta solicitud, comunicarme y conservar la constancia correspondiente, conforme a la <a href="#privacidad">política de privacidad</a>.</span></label><div id="leadStatus" class="form-status" hidden></div><div><button class="button primary" type="submit">Autorizar y enviar solicitud</button><button class="button ghost" type="button" id="restart">Volver a empezar</button></div></form>`;
      result.querySelector('#restart').onclick=()=>{result.hidden=true;form.hidden=false;form.reset();goHome()};
      result.focus({preventScroll:true});result.scrollIntoView({behavior:'smooth',block:'start'});
      const contactForm=result.querySelector('#contactForm'),requestId=crypto.randomUUID();
      contactForm.addEventListener('submit',async ev=>{
        ev.preventDefault();const status=result.querySelector('#leadStatus'),button=contactForm.querySelector('button[type="submit"]'),contact=Object.fromEntries(new FormData(contactForm).entries());
        status.hidden=false;status.textContent='Enviando solicitud…';button.disabled=true;
        const name=`${contact.first_name} ${contact.last_name}`.trim();const storedSummary=contact.summary||'';
        try{const response=await fetch('/api/consultations',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({...answers,request_id:requestId,name,phone:contact.phone,email:contact.email,address:contact.address,preferred_at:contact.preferred_at,summary:storedSummary,entity:answers.entity_choice,order:answers.support==='order'?'si':'por_confirmar',action:`orientacion_${answers.problem}`,consent:true})});const payload=await response.json();if(!response.ok)throw new Error(payload.error||'No fue posible guardar la solicitud.');try{sessionStorage.setItem('salvacion-m-contacto',JSON.stringify({first_name:contact.first_name,last_name:contact.last_name,phone:contact.phone,address:contact.address,email:contact.email}))}catch{}result.innerHTML=`<p class="eyebrow">Solicitud recibida</p><h3>Gracias, ${escape(contact.first_name)}.</h3><p class="reference">Referencia ${payload.reference}</p><p>Tu solicitud fue registrada con la autorización otorgada. La fecha preferida, si la indicaste, queda pendiente de confirmación. Volverás al inicio en unos segundos.</p><button class="button primary" type="button" id="goHome">Volver al inicio</button>`;result.querySelector('#goHome').onclick=goHome;setTimeout(goHome,5000)}catch(err){status.className='form-status error';status.textContent=err.message;button.disabled=false}
      });
    },true);
  })();

